r=Path('benchmarks/dense500');aid='PMC13587162.1';s=json.load(open(r/'sources'/f'{aid}.json'));sg={x['segment_id']:x['text'] for x in s['segments']};m=json.load(open(r/'figure-assets'/f'{aid}.json'));out=[]
def ev(sid,q):assert q in sg[sid];return {'segment_id':sid,'quote':q}
